def main_solution(num):
    denominations = {'$100': 0, '$50': 0, '$20': 0, '$10': 0, '$5': 0, '$2': 0, '$1': 0}
    remaining = num

    while remaining > 0:
        if remaining >= 100:
            denominations['$100'] += 1
            remaining -= 100
        elif remaining >= 50:
            denominations['$50'] += 1
            remaining -= 50
        elif remaining >= 20:
            denominations['$20'] += 1
            remaining -= 20
        elif remaining >= 10:
            denominations['$10'] += 1
            remaining -= 10
        elif remaining >= 5:
            denominations['$5'] += 1
            remaining -= 5
        elif remaining >= 2:
            denominations['$2'] += 1
            remaining -= 2
        else:
            denominations['$1'] += 1
            remaining -= 1

    total = sum(denominations.values())
    filtered_denominations = {k: v for k, v in denominations.items() if v > 0}

    return {
        'total': total,
        'details': filtered_denominations
    }

