def main_solution(M):
    N = len(M)
    if N == 0:
        return 0

    visited = [0] * N

    def DFS(i):
        if visited[i] == 1:
            return 

        visited[i] = 1
        for j in range(len(M)):
            if j != i:
                if M[i][j] == 1:
                    DFS(j)

    res = 0
    for i in range(N):
        if visited[i] == 0:
            DFS(i)
            res += 1
    return res

